CREATE TYPE "CollectionType" AS ENUM ('MANUAL','DYNAMIC');CREATE TYPE "HomeRailType" AS ENUM ('HERO','COLLECTION','LIVE','MOVIES','SERIES','TOP_10');
CREATE TABLE "EditorialCollection"("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"names" JSONB NOT NULL,"description" JSONB,"type" "CollectionType" NOT NULL DEFAULT 'MANUAL',"rules" JSONB,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"publishedAt" TIMESTAMP(3),"scheduledFor" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EditorialCollection_pkey" PRIMARY KEY("id"));
CREATE TABLE "CollectionItem"("id" TEXT NOT NULL,"collectionId" TEXT NOT NULL,"mediaTitleId" TEXT,"channelId" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "CollectionItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "HomeLayout"("id" TEXT NOT NULL,"locale" TEXT NOT NULL,"countryCode" TEXT NOT NULL,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"scheduledFor" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "HomeLayout_pkey" PRIMARY KEY("id"));
CREATE TABLE "HomeRail"("id" TEXT NOT NULL,"layoutId" TEXT NOT NULL,"type" "HomeRailType" NOT NULL,"names" JSONB NOT NULL,"collectionId" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"enabled" BOOLEAN NOT NULL DEFAULT true,"rules" JSONB,CONSTRAINT "HomeRail_pkey" PRIMARY KEY("id"));
CREATE TABLE "HomeRailItem"("id" TEXT NOT NULL,"railId" TEXT NOT NULL,"mediaTitleId" TEXT,"channelId" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "HomeRailItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "ContentAuditEvent"("id" TEXT NOT NULL,"actorId" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"action" TEXT NOT NULL,"before" JSONB,"after" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ContentAuditEvent_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "EditorialCollection_slug_key" ON "EditorialCollection"("slug");CREATE INDEX "EditorialCollection_status_sortOrder_idx" ON "EditorialCollection"("status","sortOrder");CREATE UNIQUE INDEX "CollectionItem_collectionId_mediaTitleId_key" ON "CollectionItem"("collectionId","mediaTitleId");CREATE UNIQUE INDEX "CollectionItem_collectionId_channelId_key" ON "CollectionItem"("collectionId","channelId");CREATE INDEX "CollectionItem_collectionId_sortOrder_idx" ON "CollectionItem"("collectionId","sortOrder");CREATE UNIQUE INDEX "HomeLayout_locale_countryCode_key" ON "HomeLayout"("locale","countryCode");CREATE INDEX "HomeLayout_status_countryCode_locale_idx" ON "HomeLayout"("status","countryCode","locale");CREATE INDEX "HomeRail_layoutId_sortOrder_idx" ON "HomeRail"("layoutId","sortOrder");CREATE UNIQUE INDEX "HomeRailItem_railId_mediaTitleId_key" ON "HomeRailItem"("railId","mediaTitleId");CREATE UNIQUE INDEX "HomeRailItem_railId_channelId_key" ON "HomeRailItem"("railId","channelId");CREATE INDEX "HomeRailItem_railId_sortOrder_idx" ON "HomeRailItem"("railId","sortOrder");CREATE INDEX "ContentAuditEvent_entityType_entityId_createdAt_idx" ON "ContentAuditEvent"("entityType","entityId","createdAt");CREATE INDEX "ContentAuditEvent_actorId_createdAt_idx" ON "ContentAuditEvent"("actorId","createdAt");
ALTER TABLE "CollectionItem" ADD CONSTRAINT "CollectionItem_collectionId_fkey" FOREIGN KEY("collectionId") REFERENCES "EditorialCollection"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "CollectionItem" ADD CONSTRAINT "CollectionItem_mediaTitleId_fkey" FOREIGN KEY("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "CollectionItem" ADD CONSTRAINT "CollectionItem_channelId_fkey" FOREIGN KEY("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "CollectionItem" ADD CONSTRAINT "CollectionItem_one_target" CHECK(num_nonnulls("mediaTitleId","channelId")=1);
ALTER TABLE "HomeRail" ADD CONSTRAINT "HomeRail_layoutId_fkey" FOREIGN KEY("layoutId") REFERENCES "HomeLayout"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "HomeRail" ADD CONSTRAINT "HomeRail_collectionId_fkey" FOREIGN KEY("collectionId") REFERENCES "EditorialCollection"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "HomeRailItem" ADD CONSTRAINT "HomeRailItem_railId_fkey" FOREIGN KEY("railId") REFERENCES "HomeRail"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "HomeRailItem" ADD CONSTRAINT "HomeRailItem_mediaTitleId_fkey" FOREIGN KEY("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "HomeRailItem" ADD CONSTRAINT "HomeRailItem_channelId_fkey" FOREIGN KEY("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "HomeRailItem" ADD CONSTRAINT "HomeRailItem_one_target" CHECK(num_nonnulls("mediaTitleId","channelId")=1);ALTER TABLE "ContentAuditEvent" ADD CONSTRAINT "ContentAuditEvent_actorId_fkey" FOREIGN KEY("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
